create extension if not exists pgcrypto;
create table if not exists public.roles(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,scope text not null,created_at timestamptz not null default now());
insert into public.roles(code,name,scope)values('super_admin','Super Admin','platform'),('organization_owner','Organization Owner','organization'),('organization_admin','Organization Admin','organization'),('branch_manager','Branch Manager','workspace'),('sales_manager','Sales Manager','workspace'),('agent','Agent','own'),('viewer','Viewer','organization')on conflict(code)do update set name=excluded.name,scope=excluded.scope;
create table if not exists public.organizations(id uuid primary key default gen_random_uuid(),name text not null,country char(2)not null,currency char(3)not null,timezone text not null,language text not null,logo_path text,status text not null default'active',created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
