create table if not exists public.workspaces(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),name text not null,office text,branch text,status text not null default'active',created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.workspace_members(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),organization_id uuid not null references public.organizations(id),user_id uuid not null references auth.users(id),role_id uuid not null references public.roles(id),status text not null default'active',created_at timestamptz not null default now(),unique(workspace_id,user_id));
create table if not exists public.invitations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid references public.workspaces(id),email text not null,name text not null,role_id uuid not null references public.roles(id),status text not null default'pending',token_hash text not null default encode(gen_random_bytes(32),'hex'),expires_at timestamptz not null default now()+interval'7 days',invited_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(organization_id,email,status));
