create or replace function public.complete_organization_onboarding(p_organization_name text,p_country text,p_currency text,p_timezone text,p_language text,p_workspace_name text,p_office text,p_branch text,p_invitations jsonb default'[]')returns jsonb language plpgsql security definer set search_path=public as $$declare v_user uuid:=auth.uid();v_org uuid;v_workspace uuid;v_owner_role uuid;v_item jsonb;v_role uuid;begin if v_user is null then raise exception'authentication required';end if;if exists(select 1 from organization_members where user_id=v_user and status='active')then raise exception'user already belongs to an organization';end if;select id into v_owner_role from roles where code='organization_owner';insert into organizations(name,country,currency,timezone,language,created_by)values(trim(p_organization_name),upper(p_country),upper(p_currency),p_timezone,p_language,v_user)returning id into v_org;insert into organization_members(organization_id,user_id,role_id)values(v_org,v_user,v_owner_role);insert into workspaces(organization_id,name,office,branch,created_by)values(v_org,trim(p_workspace_name),nullif(trim(p_office),''),nullif(trim(p_branch),''),v_user)returning id into v_workspace;insert into workspace_members(workspace_id,organization_id,user_id,role_id)values(v_workspace,v_org,v_user,v_owner_role);for v_item in select*from jsonb_array_elements(coalesce(p_invitations,'[]'))loop select id into v_role from roles where code=v_item->>'role' and code not in('super_admin','organization_owner');if v_role is not null then insert into invitations(organization_id,workspace_id,email,name,role_id,invited_by)values(v_org,v_workspace,lower(v_item->>'email'),v_item->>'name',v_role,v_user)on conflict do nothing;end if;end loop;return jsonb_build_object('organization_id',v_org,'workspace_id',v_workspace);end$$;
