ce_id and p.deleted_at is null on conflict do nothing;end loop;return v_id;end$$;
create or replace function public.update_lead(p_lead_id uuid,p_expected_version integer,p_input jsonb)returns void language plpgsql security definer set search_path=public as $$declare v_user uuid:=auth.uid();v_lead leads%rowtype;v_role text;v_value text;begin select*into v_lead from leads where id=p_lead_id and deleted_at is null for update;if not found or not is_organization_member(v_lead.organization_id)then raise exception'lead not found';end if;v_role:=current_workspace_role(v_lead.workspace_id);if v_role not in('organization_owner','organization_admin','sales_manager')and not(v_role='agent'and v_lead.assigned_agent_id=v_user)then raise exception'insufficient lead permission';end if;if v_lead.version<>p_expected_version then raise exception'lead changed by another user';end if;update leads set name=p_input->>'name',phone=p_input->>'phone',email=nullif(p_input->>'email',''),whatsapp=nullif(p_input->>'whatsapp',''),preferred_language=p_input->>'preferredLanguage',source=p_input->>'source',status=p_input->>'status',priority=p_input->>'priority',budget=nullif(p_input->>'budget','')::numeric,currency=upper(p_input->>'currency'),buying_purpose=p_input->>'buyingPurpose',property_type=p_input->>'propertyType',preferred_locations=array(select jsonb_array_elements_text(coalesce(p_input->'preferredLocations','[]'))),bedrooms=nullif(p_input->>'bedrooms','')::integer,timeline=p_input->>'timeline',financing=p_input->>'financing',assigned_agent_id=case when v_role in('organization_owner','organization_admin','sales_manager')then nullif(p_input->>'assignedAgentId','')::uuid else assigned_agent_id end,expected_closing=nullif(p_input->>'expectedClosing','')::date,updated_by=v_user,updated_at=now(),version=version+1 where id=p_lead_id;delete from lead_tags where lead_id=p_lead_id;for v_value in select jsonb_array_elements_text(coalesce(p_input->'tags','[]'))loop insert into lead_tags(lead_id,organization_id,workspace_id,tag)values(p_lead_id,v_lead.organization_id,v_lead.workspace_id,v_value)on conflict do nothing;end loop;delete from lead_property_interests where lead_id=p_lead_id;for v_value in select jsonb_array_elements_text(coalesce(p_input->'propertyInterestIds','[]'))loop insert into lead_property_interests(lead_id,property_id,organization_id,workspace_id)select p_lead_id,p.id,v_lead.organization_id,v_lead.workspace_id from properties p where p.id=v_value::uuid and p.organization_id=v_lead.organization_id and p.workspace_id=v_lead.workspace_id and p.deleted_at is null on conflict do nothing;end loop;end$$;
