create or replace function public.can_govern_ai(p_workspace uuid)returns boolean language sql stable security definer set search_path=public as $$select public.current_workspace_role(p_workspace)in('organization_owner','organization_admin','branch_manager','sales_manager')$$;
create or replace function public.provision_ai_workforce(p_workspace uuid,p_organization uuid,p_actor uuid)returns void language plpgsql security definer set search_path=public as $$begin insert into ai_capabilities(organization_id,workspace_id,code,name,description)select p_organization,p_workspace,x.code,replace(initcap(x.code),'_',' '),'Inactive capability contract; provider execution is not configured.'from unnest(array['organization_health','revenue_forecast','priority_review','lead_prioritization','pipeline_insights','follow_up_review','property_suggestions','inventory_analysis','deal_risk_analysis','closing_checklist','task_recommendations','operations_health','campaign_guidance','listing_positioning','communication_summary','escalation_review'])x(code)on conflict(workspace_id,code)do nothing;insert into ai_employees(organization_id,workspace_id,code,name,avatar,department,responsibilities,knowledge_sources,created_by,updated_by)values(p_organization,p_workspace,'ai_ceo','Avery','AC','Executive Office',array['Organization health','Executive briefings','Cross-team priorities'],array['properties','leads','deals','operations','communications'],p_actor,p_actor),(p_organization,p_workspace,'ai_sales_director','Sofia','SD','Sales',array['Pipeline review','Lead prioritization','Sales coaching'],array['leads','deals','communications'],p_actor,p_actor),(p_organization,p_workspace,'ai_property_expert','Aria','AP','Properties',array['Property matching','Inventory gaps','Listing quality'],array['properties','leads'],p_actor,p_actor),(p_organization,p_workspace,'ai_deal_coach','Dylan','DC','Deals',array['Deal risk','Missing information','Closing readiness'],array['deals','communications'],p_actor,p_actor),(p_organization,p_workspace,'ai_operations_manager','Owen','OM','Operations',array['Workload review','Overdue work','Schedule health'],array['operations'],p_actor,p_actor),(p_organization,p_workspace,'ai_marketing_advisor','Maya','MA','Marketing',array['Campaign guidance','Listing positioning','Audience insights'],array['properties','communications'],p_actor,p_actor),(p_organization,p_workspace,'ai_support_assistant','Sam','SA','Customer Support',array['Communication review','Follow-up gaps','Service escalation'],array['communications','operations'],p_actor,p_actor)on conflict(workspace_id,code)do nothing;insert into ai_employee_capabilities(employee_id,capability_id,organization_id,workspace_id)select e.id,c.id,p_organization,p_workspace from ai_employees e join ai_capabilities c on c.workspace_id=e.workspace_id where e.workspace_id=p_workspace and((e.code='ai_ceo'and c.code in('organization_health','revenue_forecast','priority_review'))or(e.code='ai_sales_director'and c.code in('lead_prioritization','pipeline_insights','follow_up_review'))or(e.code='ai_property_expert'and c.code in('property_suggestions','inventory_analysis'))or(e.code='ai_deal_coach'and c.code in('deal_risk_analysis','closing_checklist'))or(e.code='ai_operations_manager'and c.code in('task_recommendations','operations_health'))or(e.code='ai_marketing_advisor'and c.code in('campaign_guidance','listing_positioning'))or(e.code='ai_support_assistant'and c.code in('communication_summary','escalation_review')))on conflict do nothing;end$$;
do $$declare w record;begin for w in select id,organization_id,created_by from workspaces loop perform provision_ai_workforce(w.id,w.organization_id,w.created_by);end loop;end$$;
create or replace function public.provision_ai_workforce_on_workspace()returns trigger language plpgsql security definer set search_path=public as $$begin perform provision_ai_workforce(new.id,new.organization_id,new.created_by);return new;end$$;create trigger provision_ai_workforce_after_workspace after insert on public.workspaces for each row execute function public.provision_ai_workforce_on_workspace();
create or replace function public.create_ai_knowledge(p_workspace_id uuid,p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare v_org uuid;v_id uuid;begin select organization_id into v_org from workspace_members where workspace_id=p_workspace_id and user_id=auth.uid()and status='active';if v_org is null or not can_govern_ai(p_workspace_id)then raise exception'insufficient AI governance permission';end if;insert into ai_knowledge(organization_id,workspace_id,source_type,title,description,created_by,updated_by)values(v_org,p_workspace_id,p_input->>'sourceType',p_input->>'title',nullif(p_input->>'description',''),auth.uid(),auth.uid())returning id into v_id;return v_id;end$$;
create or replace function public.decide_ai_approval(p_approval_id uuid,p_expected_version integer,p_decision text,p_reason text default null)returns void language plpgsql security definer set search_path=public as $$declare a ai_approval_queue%rowtype;begin select*into a from ai_approval_queue where id=p_approval_id for update;if not found or not can_govern_ai(a.workspace_id)then raise exception'insufficient AI approval permission';end if;if a.version<>p_expected_version then raise exception'approval changed by another user';end if;if a.status<>'pending'or p_decision not in('approved','rejected')then raise exception'invalid approval decision';end if;update ai_approval_queue set status=p_decision,reason=p_reason,decided_at=now(),decided_by=auth.uid(),version=version+1 where id=p_approval_id;if a.recommendation_id is not null then update ai_recommendations set status=p_decision,updated_at=now(),updated_by=auth.uid(),version=version+1 where id=a.recommendation_id;else update ai_tasks set status=p_decision,updated_at=now(),updated_by=auth.uid(),version=version+1 where id=a.task_id;end if;insert into activity_events(organization_id,workspace_id,event_type,title,actor_id,related_type,related_id)values(a.organization_id,a.workspace_id,'ai.approval_decided','AI recommendation '||p_decision,auth.uid(),'ai_approval',a.id);end$$;
create or replace function public.archive_ai_recommendation(p_recommendation_id uuid,p_expected_version integer)returns void language plpgsql security definer set search_path=public as $$declare r ai_recommendations%rowtype;begin select*into r from ai_recommendations where id=p_recommendation_id and deleted_at is null for update;if not found or not can_govern_ai(r.workspace_id)then raise exception'insufficient AI governance permission';end if;if r.version<>p_expected_version then raise exception'recommendation changed by another user';end if;update ai_recommendations set status='archived',deleted_at=now(),updated_at=now(),updated_by=auth.uid(),version=version+1 where id=p_recommendation_id;update ai_approval_queue set status='cancelled',version=version+1 where recommendation_id=p_recommendation_id and status='pending';end$$;
revoke all on function public.provision_ai_workforce(uuid,uuid,uuid),public.create_ai_knowledge(uuid,jsonb),public.decide_ai_approval(uuid,integer,text,text),public.archive_ai_recommendation(uuid,integer)from public;grant execute on function public.create_ai_knowledge(uuid,jsonb),public.decide_ai_approval(uuid,integer,text,text),public.archive_ai_recommendation(uuid,integer)to authenticated;

