-- Sprint 17 additive migration. Provider output is recommendation-only and always requires human approval.
create table public.ai_conversations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),employee_id uuid not null references public.ai_employees(id),prompt_key text not null,prompt_version integer not null,subject_type text,subject_id uuid,context_snapshot jsonb not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1);
create table public.ai_runtime_outputs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),conversation_id uuid not null references public.ai_conversations(id),employee_id uuid not null references public.ai_employees(id),recommendation_id uuid not null references public.ai_recommendations(id),provider text not null,model text not null,output jsonb not null,approval_status text not null default'pending' check(approval_status in('pending','approved','rejected','archived')),latency_ms integer not null,input_tokens integer not null default 0,output_tokens integer not null default 0,cost_estimate numeric(18,8)not null default 0,cache_key text not null,created_at timestamptz not null default now());
create table public.ai_response_cache(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),cache_key text not null,provider text not null,model text not null,output jsonb not null,latency_ms integer not null,input_tokens integer not null,output_tokens integer not null,cost_estimate numeric(18,8)not null default 0,created_at timestamptz not null default now(),expires_at timestamptz not null,unique(workspace_id,cache_key));
create index ai_conversations_subject_idx on public.ai_conversations(organization_id,workspace_id,subject_type,subject_id,created_at desc)where deleted_at is null;create index ai_outputs_employee_idx on public.ai_runtime_outputs(organization_id,workspace_id,employee_id,created_at desc);create index ai_cache_expiry_idx on public.ai_response_cache(workspace_id,expires_at);
update public.ai_employees set status='ready',updated_at=now(),version=version+1 where code in('ai_sales_director','ai_property_expert','ai_deal_coach','ai_ceo')and deleted_at is null;
alter table public.ai_conversations enable row level security;alter table public.ai_runtime_outputs enable row level security;alter table public.ai_response_cache enable row level security;
create policy "ai_conversations_workspace_read" on public.ai_conversations for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);create policy "ai_outputs_workspace_read" on public.ai_runtime_outputs for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);create policy "ai_cache_governor_read" on public.ai_response_cache for select to authenticated using(public.is_organization_member(organization_id)and public.can_govern_ai(workspace_id));
create or replace function public.store_ai_runtime_output(p_workspace_id uuid,p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare v_org uuid;v_employee ai_employees%rowtype;v_conversation uuid;v_recommendation uuid;v_output uuid;v_approval uuid;begin select organization_id into v_org from workspace_members where workspace_id=p_workspace_id and user_id=auth.uid()and status='active';if v_org is null or not can_govern_ai(p_workspace_id)then raise exception'insufficient AI runtime permission';end if;select*into v_employee from ai_employees where id=(p_input->>'employeeId')::uuid and organization_id=v_org and workspace_id=p_workspace_id and deleted_at is null;if not found or v_employee.code not in('ai_sales_director','ai_property_expert','ai_deal_coach','ai_ceo')then raise exception'invalid runtime employee';end if;if coalesce((p_input->'output'->>'approvalRequired')::boolean,false)is not true then raise exception'AI output must require approval';end if;insert into ai_conversations(organization_id,workspace_id,employee_id,prompt_key,prompt_version,subject_type,subject_id,context_snapshot,created_by)values(v_org,p_workspace_id,v_employee.id,p_input->>'promptKey',(p_input->>'promptVersion')::integer,nullif(p_input->'context'->'subject'->>'type',''),nullif(p_input->'context'->'subject'->>'id','')::uuid,p_input->'context',auth.uid())returning id into v_conversation;insert into ai_recommendations(organization_id,workspace_id,employee_id,recommendation_type,title,summary,confidence,status,subject_type,subject_id,evidence,created_by,updated_by)values(v_org,p_workspace_id,v_employee.id,p_input->>'promptKey',p_input->'output'->>'summary',p_input->'output'->>'summary',(p_input->'output'->>'confidence')::numeric,'pending_approval',nullif(p_input->'context'->'subject'->>'type',''),nullif(p_input->'context'->'subject'->>'id','')::uuid,p_input->'output'->'referencedCrmRecords',auth.uid(),auth.uid())returning id into v_recommendation;insert into ai_runtime_outputs(organization_id,workspace_id,conversation_id,employee_id,recommendation_id,provider,model,output,latency_ms,input_tokens,output_tokens,cost_estimate,cache_key)values(v_org,p_workspace_id,v_conversation,v_employee.id,v_recommendation,p_input->>'provider',p_input->>'model',p_input->'output',(p_input->>'latencyMs')::integer,(p_input->>'inputTokens')::integer,(p_input->>'outputTokens')::integer,(p_input->>'costEstimate')::numeric,p_input->>'cacheKey')returning id into v_output;insert into ai_approval_queue(organization_id,workspace_id,recommendation_id,status)values(v_org,p_workspace_id,v_recommendation,'pending')returning id into v_approval;insert into ai_response_cache(organization_id,workspace_id,cache_key,provider,model,output,latency_ms,input_tokens,output_tokens,cost_estimate,expires_at)values(v_org,p_workspace_id,p_input->>'cacheKey',p_input->>'provider',p_input->>'model',p_input->'output',(p_input->>'latencyMs')::integer,(p_input->>'inputTokens')::integer,(p_input->>'outputTokens')::integer,(p_input->>'costEstimate')::numeric,now()+interval'15 minutes')on conflict(workspace_id,cache_key)do update set output=excluded.output,provider=excluded.provider,model=excluded.model,latency_ms=excluded.latency_ms,input_tokens=excluded.input_tokens,output_tokens=excluded.output_tokens,cost_estimate=excluded.cost_estimate,created_at=now(),expires_at=excluded.expires_at;insert into activity_events(organization_id,workspace_id,event_type,title,actor_id,related_type,related_id)values(v_org,p_workspace_id,'ai.recommendation_created','AI recommendation awaiting approval',auth.uid(),'ai_recommendation',v_recommendation);return v_output;end$$;
revoke all on function public.store_ai_runtime_output(uuid,jsonb)from public;grant execute on function public.store_ai_runtime_output(uuid,jsonb)to authenticated;

