-- Sprint 18 additive migration. Provider control-plane metadata only; secrets and credentials are never stored.
create table public.integration_providers(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,description text not null,version text not null default'1.0',auth_method text not null,scopes text[]not null default'{}',category text not null,active boolean not null default true,future boolean not null default false,rate_limit_metadata jsonb not null default'{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());insert into public.integration_providers(code,name,description,auth_method,scopes,category,future)values('openai','OpenAI','LeadEstate AI Runtime provider','api_key','{}','ai',false),('gmail','Gmail','Customer email synchronization','oauth2','{"gmail.readonly"}','communications',false),('google_calendar','Google Calendar','Meeting and availability synchronization','oauth2','{"calendar.readonly"}','operations',false),('whatsapp_business','WhatsApp Business','Official business messaging provider','webhook_secret','{}','communications',false),('stripe','Stripe','Subscription payment provider','api_key','{}','billing',false),('google_maps','Google Maps','Property geocoding and maps provider','api_key','{}','maps',false),('supabase_storage','Supabase Storage','Organization asset storage','service_role','{}','storage',false),('twilio','Twilio','Future communications provider','none','{}','communications',true),('microsoft_365','Microsoft 365','Future productivity provider','none','{}','productivity',true),('anthropic','Anthropic','Future AI provider','none','{}','ai',true),('gemini','Gemini','Future AI provider','none','{}','ai',true)on conflict(code)do nothing;
create table public.integration_connections(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),provider_id uuid not null references public.integration_providers(id),status text not null default'disconnected' check(status in('connected','disconnected','degraded','disabled')),configuration jsonb not null default'{}',last_sync_at timestamptz,enabled_at timestamptz,disabled_at timestamptz,created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1,unique(workspace_id,provider_id));
create table public.integration_webhooks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),provider_id uuid not null references public.integration_providers(id),direction text not null check(direction in('incoming','outgoing')),event_type text not null,status text not null check(status in('pending','processed','failed','replay_queued','cancelled')),signature_valid boolean not null default false,idempotency_key text not null,payload_hash text not null,received_at timestamptz not null default now(),processed_at timestamptz,attempts integer not null default 0,last_error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1,unique(provider_id,idempotency_key));
create table public.integration_sync_history(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),provider_id uuid not null references public.integration_providers(id),entity_type text not null,direction text not null check(direction in('inbound','outbound','bidirectional')),started_at timestamptz not null,completed_at timestamptz,duration_ms integer,status text not null,records_processed integer not null default 0,created_at timestamptz not null default now());
create table public.integration_retry_queue(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),provider_id uuid not null references public.integration_providers(id),webhook_id uuid references public.integration_webhooks(id),sync_id uuid references public.integration_sync_history(id),event_type text not null,status text not null default'queued' check(status in('queued','running','succeeded','failed','cancelled')),attempts integer not null default 0,max_attempts integer not null default 5,next_attempt_at timestamptz,last_error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version integer not null default 1,check(webhook_id is not null or sync_id is not null));
create table public.integration_logs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),provider_id uuid not null references public.integration_providers(id),actor_id uuid references auth.users(id),level text not null check(level in('debug','info','warning','error','audit')),event text not null,message text not null,duration_ms integer,audit_event boolean not null default false,correlation_id uuid not null default gen_random_uuid(),occurred_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1);
create table public.integration_health(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),provider_id uuid not null references public.integration_providers(id),status text not null check(status in('healthy','degraded','unavailable','unknown')),latency_ms integer,failure_rate numeric(6,5)not null default 0,retry_count integer not null default 0,last_success_at timestamptz,last_failure_at timestamptz,checked_at timestamptz not null default now(),details jsonb not null default'{}',unique(workspace_id,provider_id));
create table public.integration_secrets_metadata(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),provider_id uuid not null references public.integration_providers(id),secret_name text not null,environment text not null check(environment in('development','staging','production')),status text not null default'missing' check(status in('missing','configured','rotation_required','disabled')),last_rotated_at timestamptz,created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1,unique(workspace_id,provider_id,secret_name,environment));
create index integration_webhooks_status_idx on public.integration_webhooks(organization_id,workspace_id,status,received_at desc)where deleted_at is null;create index integration_retry_status_idx on public.integration_retry_queue(organization_id,workspace_id,status,next_attempt_at);create index integration_logs_recent_idx on public.integration_logs(organization_id,workspace_id,occurred_at desc)where deleted_at is null;create index integration_sync_recent_idx on public.integration_sync_history(organization_id,workspace_id,started_at desc);
alter table public.integration_providers enable row level security;alter table public.integration_connections enable row level security;alter table public.integration_webhooks enable row level security;alter table public.integration_sync_history enable row level security;alter table public.integration_retry_queue enable row level security;alter table public.integration_logs enable row level security;alter table public.integration_health enable row level security;alter table public.integration_secrets_metadata enable row level security;
create or replace function public.can_manage_integrations(p_workspace uuid)returns boolean language sql stable security definer set search_path=public as $$select public.current_workspace_role(p_workspace)='organization_owner'or coalesce(auth.jwt()->'app_metadata'->>'role','')='super_admin'$$;
create policy "integration_providers_authenticated_read" on public.integration_providers for select to authenticated using(active);create policy "integration_connections_governor_read" on public.integration_connections for select to authenticated using(public.can_manage_integrations(workspace_id));create policy "integration_webhooks_governor_read" on public.integration_webhooks for select to authenticated using(public.can_manage_integrations(workspace_id));create policy "integration_sync_governor_read" on public.integration_sync_history for select to authenticated using(public.can_manage_integrations(workspace_id));create policy "integration_retry_governor_read" on public.integration_retry_queue for select to authenticated using(public.can_manage_integrations(workspace_id));create policy "integration_logs_governor_read" on public.integration_logs for select to authenticated using(public.can_manage_integrations(workspace_id));create policy "integration_health_governor_read" on public.integration_health for select to authenticated using(public.can_manage_integrations(workspace_id));create policy "integration_secret_metadata_governor_read" on public.integration_secrets_metadata for select to authenticated using(public.can_manage_integrations(workspace_id));
create or replace function public.provision_workspace_integrations(p_workspace uuid,p_organization uuid,p_actor uuid)returns void language plpgsql security definer set search_path=public as $$begin insert into integration_connections(organization_id,workspace_id,provider_id,status,created_by,updated_by)select p_organization,p_workspace,id,case when code='openai'and current_setting('app.openai_configured',true)='true'then'connected'else'disconnected'end,p_actor,p_actor from integration_providers where active on conflict(workspace_id,provider_id)do nothing;insert into integration_health(organization_id,workspace_id,provider_id,status)select p_organization,p_workspace,id,'unknown'from integration_providers where active on conflict(workspace_id,provider_id)do nothing;end$$;do $$declare w record;begin for w in select id,organization_id,created_by from workspaces loop perform provision_workspace_integrations(w.id,w.organization_id,w.created_by);end loop;end$$;create or replace function public.provision_integrations_on_workspace()returns trigger language plpgsql security definer set search_path=public as $$begin perform provision_workspace_integrations(new.id,new.organization_id,new.created_by);return new;end$$;create trigger provision_integrations_after_workspace after insert on public.workspaces for each row execute function public.provision_integrations_on_workspace();
create or replace function public.set_integration_enabled(p_connection_id uuid,p_expected_version integer,p_enabled boolean)returns void language plpgsql security definer set search_path=public as $$declare c integration_connections%rowtype;begin select*into c from integration_connections where id=p_connection_id and deleted_at is null for update;if not found or not can_manage_integrations(c.workspace_id)then raise exception'insufficient integration permission';end if;if c.version<>p_expected_version then raise exception'integration changed by another user';end if;update integration_connections set status=case when p_enabled then'connected'else'disabled'end,enabled_at=case when p_enabled then now()else enabled_at end,disabled_at=case when not p_enabled then now()else null end,updated_by=auth.uid(),updated_at=now(),version=version+1 where id=c.id;insert into integration_logs(organization_id,workspace_id,provider_id,actor_id,level,event,message,audit_event)values(c.organization_id,c.workspace_id,c.provider_id,auth.uid(),'audit',case when p_enabled then'provider.enabled'else'provider.disabled'end,case when p_enabled then'Provider enabled'else'Provider disabled'end,true);end$$;
create or replace function public.rotate_integration_secret_metadata(p_metadata_id uuid,p_expected_version integer)returns void language plpgsql security definer set search_path=public as $$declare s integration_secrets_metadata%rowtype;begin select*into s from integration_secrets_metadata where id=p_metadata_id and deleted_at is null for update;if not found or not can_manage_integrations(s.workspace_id)then raise exception'insufficient secret metadata permission';end if;if s.version<>p_expected_version then raise exception'metadata changed by another user';end if;update integration_secrets_metadata set status='rotation_required',last_rotated_at=now(),updated_by=auth.uid(),updated_at=now(),version=version+1 where id=s.id;insert into integration_logs(organization_id,workspace_id,provider_id,actor_id,level,event,message,audit_event)values(s.organization_id,s.workspace_id,s.provider_id,auth.uid(),'audit','secret.rotation_recorded','Secret rotation metadata updated; value not accessed',true);end$$;
create or replace function public.replay_integration_webhook(p_webhook_id uuid,p_expected_version integer)returns void language plpgsql security definer set search_path=public as $$declare w integration_webhooks%rowtype;begin select*into w from integration_webhooks where id=p_webhook_id and deleted_at is null for update;if not found or not can_manage_integrations(w.workspace_id)then raise exception'insufficient webhook permission';end if;if w.version<>p_expected_version then raise exception'webhook changed by another user';end if;if not w.signature_valid then raise exception'webhook signature was not validated';end if;if w.attempts>=5 then raise exception'replay attempt limit reached';end if;if exists(select 1 from integration_retry_queue where webhook_id=w.id and status in('queued','running'))then raise exception'webhook replay already queued';end if;update integration_webhooks set status='replay_queued',attempts=attempts+1,updated_at=now(),version=version+1 where id=w.id;insert into integration_retry_queue(organization_id,workspace_id,provider_id,webhook_id,event_type,status,next_attempt_at)values(w.organization_id,w.workspace_id,w.provider_id,w.id,w.event_type,'queued',now());insert into integration_logs(organization_id,workspace_id,provider_id,actor_id,level,event,message,audit_event)values(w.organization_id,w.workspace_id,w.provider_id,auth.uid(),'audit','webhook.replay_queued','Validated webhook replay queued',true);end$$;
create or replace function public.retry_integration_sync(p_retry_id uuid,p_expected_version integer)returns void language plpgsql security definer set search_path=public as $$declare r integration_retry_queue%rowtype;begin select*into r from integration_retry_queue where id=p_retry_id for update;if not found or not can_manage_integrations(r.workspace_id)then raise exception'insufficient retry permission';end if;if r.version<>p_expected_version then raise exception'retry changed by another user';end if;if r.status not in('failed','cancelled')or r.attempts>=r.max_attempts then raise exception'retry is not eligible';end if;update integration_retry_queue set status='queued',next_attempt_at=now(),updated_at=now(),version=version+1 where id=r.id;insert into integration_logs(organization_id,workspace_id,provider_id,actor_id,level,event,message,audit_event)values(r.organization_id,r.workspace_id,r.provider_id,auth.uid(),'audit','sync.retry_queued','Integration retry queued',true);end$$;
create or replace function public.archive_integration_log(p_log_id uuid,p_expected_version integer)returns void language plpgsql security definer set search_path=public as $$declare l integration_logs%rowtype;begin select*into l from integration_logs where id=p_log_id and deleted_at is null for update;if not found or not can_manage_integrations(l.workspace_id)then raise exception'insufficient log permission';end if;if l.version<>p_expected_version then raise exception'log changed by another user';end if;if l.audit_event then raise exception'audit events cannot be archived';end if;update integration_logs set deleted_at=now(),version=version+1 where id=l.id;insert into integration_logs(organization_id,workspace_id,provider_id,actor_id,level,event,message,audit_event)values(l.organization_id,l.workspace_id,l.provider_id,auth.uid(),'audit','log.archived','Non-audit integration log archived',true);end$$;
revoke all on function public.provision_workspace_integrations(uuid,uuid,uuid),public.set_integration_enabled(uuid,integer,boolean),public.rotate_integration_secret_metadata(uuid,integer),public.replay_integration_webhook(uuid,integer),public.retry_integration_sync(uuid,integer),public.archive_integration_log(uuid,integer)from public;grant execute on function public.set_integration_enabled(uuid,integer,boolean),public.rotate_integration_secret_metadata(uuid,integer),public.replay_integration_webhook(uuid,integer),public.retry_integration_sync(uuid,integer),public.archive_integration_log(uuid,integer)to authenticated;

