create or replace function public.check_subscription_limit(p_workspace_id uuid,p_metric text,p_increment numeric default 1)returns jsonb language plpgsql security definer set search_path=public as $$declare v_usage numeric:=0;v_limit numeric;v_plan text;begin if not public.is_organization_member((select organization_id from workspaces where id=p_workspace_id))then raise exception'insufficient subscription permission';end if;select coalesce(u.quantity,0),l.limit_value,p.code into v_usage,v_limit,v_plan from subscriptions s join subscription_plans p on p.id=s.plan_id left join organization_limits l on l.workspace_id=s.workspace_id and l.metric=p_metric left join organization_usage u on u.workspace_id=s.workspace_id and u.metric=p_metric and current_date between u.period_start and u.period_end where s.workspace_id=p_workspace_id and s.deleted_at is null;return jsonb_build_object('allowed',v_limit is null or v_usage+p_increment<=v_limit,'usage',v_usage,'limit',v_limit,'plan_code',v_plan);end$$;
create or replace function public.process_stripe_event(p_event_id text,p_event_type text,p_payload jsonb)returns void language plpgsql security definer set search_path=public as $$declare v_org uuid;v_workspace uuid;begin if current_setting('role',true)<>'service_role'then raise exception'service role required';end if;v_org=nullif(coalesce(p_payload->'metadata'->>'organization_id',p_payload->'subscription_details'->'metadata'->>'organization_id'),'')::uuid;select id into v_workspace from workspaces where organization_id=v_org and status='active'order by created_at limit 1;insert into provider_webhook_events(provider,event_id,event_type,organization_id,workspace_id,payload,status,processed_at)values('stripe',p_event_id,p_event_type,v_org,v_workspace,p_payload,'processed',now())on conflict(provider,event_id)do nothing;if not found then return;end if;insert into subscription_events(organization_id,workspace_id,provider,event_id,event_type,payload)values(v_org,v_workspace,'stripe',p_event_id,p_event_type,p_payload)on conflict(event_id)do nothing;if p_event_type like'customer.subscription.%'then update subscriptions set provider='stripe',provider_customer_id=p_payload->>'customer',provider_subscription_id=p_payload->>'id',status=case p_payload->>'status'when'active'then'active'when'trialing'then'trialing'when'past_due'then'past_due'when'canceled'then'cancelled'else status end,current_period_ends_at=to_timestamp(coalesce((p_payload->>'current_period_end')::bigint,extract(epoch from current_period_ends_at)::bigint)),cancel_at_period_end=coalesce((p_payload->>'cancel_at_period_end')::boolean,false),updated_at=now(),version=version+1 where organization_id=v_org and workspace_id=v_workspace;elsif p_event_type like'invoice.%'then insert into invoices(organization_id,workspace_id,subscription_id,invoice_number,status,currency,subtotal,tax,issued_at,due_at,paid_at,download_url,provider_invoice_id,created_by,metadata)select v_org,v_workspace,s.id,coalesce(p_payload->>'number',p_payload->>'id'),case p_payload->>'status'when'paid'then'paid'when'open'then'open'when'void'then'void'else'draft'end,upper(coalesce(p_payload->>'currency','usd')),coalesce((p_payload->>'subtotal')::numeric/100,0),coalesce((p_payload->>'tax')::numeric/100,0),to_timestamp((p_payload->>'created')::bigint),case when p_payload->>'due_date'is null then null else to_timestamp((p_payload->>'due_date')::bigint)end,case when p_payload->>'status'='paid'then now()end,p_payload->>'hosted_invoice_url',p_payload->>'id',s.created_by,p_payload from subscriptions s where s.workspace_id=v_workspace on conflict(provider_invoice_id)do update set status=excluded.status,paid_at=excluded.paid_at,download_url=excluded.download_url,updated_at=now();end if;end$$;
create or replace function public.connect_whatsapp(p_workspace_id uuid,p_phone_number_id text,p_business_account_id text,p_token_ciphertext text,p_token_iv text,p_token_tag text)returns void language plpgsql security definer set search_path=public as $$declare v_org uuid;begin select organization_id into v_org from workspaces where id=p_workspace_id;if not public.can_manage_integrations(p_workspace_id)then raise exception'insufficient integration permission';end if;insert into whatsapp_connections(organization_id,workspace_id,business_account_id,phone_number_id,access_token_ciphertext,access_token_iv,access_token_tag,created_by,updated_by)values(v_org,p_workspace_id,p_business_account_id,p_phone_number_id,p_token_ciphertext,p_token_iv,p_token_tag,auth.uid(),auth.uid())on conflict(workspace_id)do update set business_account_id=excluded.business_account_id,phone_number_id=excluded.phone_number_id,access_token_ciphertext=excluded.access_token_ciphertext,access_token_iv=excluded.access_token_iv,access_token_tag=excluded.access_token_tag,status='connected',deleted_at=null,updated_by=auth.uid(),updated_at=now(),version=whatsapp_connections.version+1;end$$;
create or replace function public.disconnect_whatsapp(p_workspace_id uuid)returns void language plpgsql security definer set search_path=public as $$begin if not public.can_manage_integrations(p_workspace_id)then raise exception'insufficient integration permission';end if;update whatsapp_connections set status='disconnected',deleted_at=now(),updated_by=auth.uid(),updated_at=now(),version=version+1 where workspace_id=p_workspace_id;end$$;
create or replace function public.get_whatsapp_delivery_credential(p_workspace_id uuid)returns table(phone_number_id text,access_token_ciphertext text,access_token_iv text,access_token_tag text)language plpgsql security definer set search_path=public as $$begin if not public.is_organization_member((select organization_id from workspaces where id=p_workspace_id))then raise exception'insufficient messaging permission';end if;return query select w.phone_number_id,w.access_token_ciphertext,w.access_token_iv,w.access_token_tag from whatsapp_connections w where w.workspace_id=p_workspace_id and w.status='connected'and w.deleted_at is null;end$$;
create or replace function public.process_whatsapp_message(p_connection_id uuid,p_organization_id uuid,p_workspace_id uuid,p_event_id text,p_message jsonb)returns void language plpgsql security definer set search_path=public as $$declare v_thread uuid;v_comm uuid;begin if current_setting('role',true)<>'service_role'then raise exception'service role required';end if;insert into provider_webhook_events(provider,event_id,event_type,organization_id,workspace_id,payload,status,processed_at)values('whatsapp',p_event_id,'message',p_organization_id,p_workspace_id,p_message,'processed',now())on conflict(provider,event_id)do nothing;if not found then return;end if;select id into v_thread from communication_threads where workspace_id=p_workspace_id and metadata->>'whatsapp_phone'=p_message->>'from'and deleted_at is null limit 1;if v_thread is null then insert into communication_threads(organization_id,workspace_id,subject,related_type,status,unread_count,last_activity_at,created_by,updated_by,metadata)values(p_organization_id,p_workspace_id,'WhatsApp · '||(p_message->>'from'),'customer','open',1,now(),(select created_by from workspaces where id=p_workspace_id),(select created_by from workspaces where id=p_workspace_id),jsonb_build_object('whatsapp_phone',p_message->>'from'))returning id into v_thread;end if;insert into communications(organization_id,workspace_id,thread_id,channel,direction,status,body,external_id,metadata,occurred_at)values(p_organization_id,p_workspace_id,v_thread,'whatsapp','inbound','received',coalesce(p_message->>'text','['||(p_message->>'type')||']'),p_message->>'id',p_message,to_timestamp((p_message->>'timestamp')::bigint))returning id into v_comm;insert into whatsapp_messages(organization_id,workspace_id,connection_id,provider_message_id,communication_id,direction,sender,recipient,message_type,text_body,media_metadata,status,provider_timestamp)values(p_organization_id,p_workspace_id,p_connection_id,p_message->>'id',v_comm,'inbound',p_message->>'from',p_message->>'to',p_message->>'type',p_message->>'text',coalesce(p_message->'media','{}'), 'received',to_timestamp((p_message->>'timestamp')::bigint));update communication_threads set unread_count=unread_count+1,last_activity_at=now(),updated_at=now(),version=version+1 where id=v_thread;end$$;
create or replace function public.process_whatsapp_status(p_provider_message_id text,p_status text,p_event_id text,p_payload jsonb)returns void language plpgsql security definer set search_path=public as $$begin if current_setting('role',true)<>'service_role'then raise exception'service role required';end if;insert into provider_webhook_events(provider,event_id,event_type,payload,status,processed_at)values('whatsapp',p_event_id,'status',p_payload,'processed',now())on conflict(provider,event_id)do nothing;if not found then return;end if;update whatsapp_messages set status=p_status,updated_at=now()where provider_message_id=p_provider_message_id;update communications set status=p_status where external_id=p_provider_message_id and channel='whatsapp';end$$;
create or replace function public.enqueue_notification(p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;v_channel text;begin insert into notification_events(organization_id,workspace_id,user_id,category,title,body,priority,dedupe_key)values((p_input->>'organizationId')::uuid,(p_input->>'workspaceId')::uuid,nullif(p_input->>'userId','')::uuid,p_input->>'category',p_input->>'title',p_input->>'body',coalesce(p_input->>'priority','normal'),p_input->>'dedupeKey')on conflict(organization_id,dedupe_key)do update set title=excluded.title returning id into v_id;for v_channel in select jsonb_array_elements_text(coalesce(p_input->'channels','["in_app"]'))loop insert into notification_queue(organization_id,workspace_id,notification_id,channel,idempotency_key)values((p_input->>'organizationId')::uuid,(p_input->>'workspaceId')::uuid,v_id,v_channel,v_id||':'||v_channel)on conflict(idempotency_key)do nothing;end loop;return v_id;end$$;
create or replace function public.dismiss_notification(p_notification_id uuid)returns void language plpgsql security definer set search_path=public as $$update notification_events set dismissed_at=now()where id=p_notification_id and public.is_organization_member(organization_id)and(user_id is null or user_id=auth.uid())$$;
create or replace function public.generate_demo_organization()returns jsonb language plpgsql security definer set search_path=public as $$declare u uuid:=auth.uid();o uuid;w uuid;r uuid;p uuid;l uuid;d uuid;t uuid;begin if u is null then raise exception'authentication required';end if;if exists(select 1 from demo_organizations where owner_id=u)then select organization_id,workspace_id into o,w from demo_organizations where owner_id=u;return jsonb_build_object('organization_id',o,'workspace_id',w);end if;select id into r from roles where code='organization_owner';insert into organizations(name,country,currency,timezone,language,created_by)values('LeadEstate Demo Realty','IN','INR','Asia/Kolkata','en',u)returning id into o;insert into organization_members(organization_id,user_id,role_id)values(o,u,r);insert into workspaces(organization_id,name,office,branch,created_by)values(o,'Demo Workspace','Bengaluru','Central',u)returning id into w;insert into workspace_members(workspace_id,organization_id,user_id,role_id)values(w,o,u,r);insert into properties(organization_id,workspace_id,reference,title,property_type,listing_type,status,country_code,city,address,sale_price,currency,bedrooms,bathrooms,area,created_by,updated_by,published,featured)values(o,w,'DEMO-P-001','Skyline Residences','apartment','sale','available','IN','Bengaluru','Indiranagar',18500000,'INR',3,3,1850,u,u,true,true)returning id into p;insert into leads(organization_id,workspace_id,name,phone,email,source,status,priority,budget,currency,preferred_locations,lead_score,temperature,created_by,updated_by)values(o,w,'Aarav Mehta','+919876543210','aarav@example.com','website','qualified','high',20000000,'INR','{"Indiranagar","Koramangala"}',86,'hot',u,u)returning id into l;insert into deals(organization_id,workspace_id,reference,name,lead_id,property_id,stage_id,value,currency,probability,created_by,updated_by)values(o,w,'DEMO-D-001','Skyline purchase',l,p,'new_lead',18500000,'INR',65,u,u)returning id into d;insert into communication_threads(organization_id,workspace_id,subject,related_type,related_id,status,created_by,updated_by)values(o,w,'Aarav · Skyline','lead',l,'open',u,u)returning id into t;insert into communications(organization_id,workspace_id,thread_id,channel,direction,status,body,user_id)values(o,w,t,'email','inbound','received','Interested in a viewing this weekend.',u),(o,w,t,'whatsapp','outbound','delivered','Our agent will share suitable times.',u);insert into meetings(organization_id,workspace_id,title,meeting_type,starts_at,ends_at,related_type,related_id,created_by,updated_by)values(o,w,'Skyline property consultation','customer',now()+interval'1 day',now()+interval'1 day 1 hour','lead',l,u,u);insert into demo_organizations(organization_id,workspace_id,owner_id,metadata)values(o,w,u,jsonb_build_object('properties',1,'leads',1,'deals',1,'agents',1,'communications',2,'meetings',1));return jsonb_build_object('organization_id',o,'workspace_id',w);end$$;
revoke all on function public.process_stripe_event(text,text,jsonb),public.process_whatsapp_message(uuid,uuid,uuid,text,jsonb),public.process_whatsapp_status(text,text,text,jsonb),public.get_whatsapp_delivery_credential(uuid),public.connect_whatsapp(uuid,text,text,text,text,text),public.disconnect_whatsapp(uuid),public.check_subscription_limit(uuid,text,numeric),public.enqueue_notification(jsonb),public.dismiss_notification(uuid),public.generate_demo_organization()from public;grant execute on function public.get_whatsapp_delivery_credential(uuid),public.connect_whatsapp(uuid,text,text,text,text,text),public.disconnect_whatsapp(uuid),public.check_subscription_limit(uuid,text,numeric),public.dismiss_notification(uuid),public.generate_demo_organization()to authenticated;grant execute on function public.process_stripe_event(text,text,jsonb),public.process_whatsapp_message(uuid,uuid,uuid,text,jsonb),public.process_whatsapp_status(text,text,text,jsonb),public.enqueue_notification(jsonb)to service_role;

